describe('Dropdown Menu Keyboard Navigation', () => {
  beforeEach(() => {
    cy.visit('/dropdown');
  });

  it('should navigate dropdown menu items using arrow keys', () => {
    // Verify dropdown is visible
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Verify initial focus is on first item
    cy.get('[data-testid="dropdown-item-1"]').should('have.focus');

    // Press down arrow key to move focus to next item
    cy.get('body').type('{down arrow}');
    cy.get('[data-testid="dropdown-item-2"]').should('have.focus');

    // Press down arrow key again to move to last item
    cy.get('body').type('{down arrow}');
    cy.get('[data-testid="dropdown-item-3"]').should('have.focus');

    // Press up arrow key to move focus to previous item
    cy.get('body').type('{up arrow}');
    cy.get('[data-testid="dropdown-item-2"]').should('have.focus');

    // Press down arrow key to move back to first item
    cy.get('body').type('{down arrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.focus');

    // Verify navigation works in both directions
    cy.get('body').type('{up arrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.focus');

    // Verify focus returns to first item when reaching top or bottom
    cy.get('body').type('{down arrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.focus');
  });

  it('should not navigate when dropdown is closed', () => {
    // Close dropdown menu
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="dropdown-close-btn"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');

    // Verify dropdown is closed
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');

    // Press arrow keys should not navigate
    cy.get('body').type('{down arrow}');
    cy.get('body').type('{up arrow}');

    // Verify no focus change occurs
    cy.get('[data-testid="dropdown-item-1"]').should('not.have.focus');
  });
});
